import csv,math,hashlib,pathlib
src=pathlib.Path('outputs/shared22_eight_source_evidence_matrix.csv');rows=list(csv.DictReader(src.open()));assert len(rows)==22 and len({x['variant'] for x in rows})==22
prefix=['atkins_FI','ye_FFS','mak_FI','mak_FP','hfrs','ukb_insomnia','mvp_insomnia','finngen_insomnia']
def pformat(x):
 x=float(x)
 return f'{x:.3g}' if x>=.001 else f'{x:.2g}'
parts=['# Twenty-two shared-direction candidates: mentor table','', 'Each row is aligned to the **shared count’s allele**. The MVP odds ratio is per copy of that allele, relative to the listed other allele, reconstructed from source-rounded estimates; it is not an absolute risk. FI and FFS p-values are from the original Atkins and Ye GWAS. The last column counts the eight available GWAS results with a positive point estimate and nominal p < 0.05; it is a descriptive checklist, **not a count of independent replications**.','', '| Variant | Counted / other allele | Nearest gene-body label | MVP insomnia OR, approx. | FI p | FFS p | Positive and nominal / 8 |','|---|---|---|---:|---:|---:|---:|']
for r in rows:
 vals=[float(r[p+'_p'])<.05 and float(r[p+'_beta_aligned'])>0 for p in prefix];n=sum(vals);assert (n==8)==(r['all_eight_nominal_same_sign']=='True')
 odds=math.exp(float(r['mvp_insomnia_beta_aligned']));assert odds>1
 parts.append('| {v} | {a} / {b} | {g} | {or_:.3f} | {fi} | {ffs} | {n} |'.format(v=r['variant'],a=r['score_counted_allele'],b=r['other_allele'],g=r['nearest_gene_body_positional'],or_=odds,fi=pformat(r['atkins_FI_p']),ffs=pformat(r['ye_FFS_p']),n=n))
parts += ['', 'The eight results are Atkins FI, Ye FFS, Mak FI, Mak physical phenotype, Finnish HFRS, UKB insomnia, MVP insomnia and FinnGen insomnia. Selection used prior insomnia–FI results plus nominal associations in MVP insomnia and HFRS, so those tests are not independent confirmation. UK Biobank appears in multiple GWAS, FinnGen releases may overlap, and p-values are not adjusted for this selection. A source with a p-value ≥0.05 is not proof of no effect. The two FOXP2 rows with 8/8 are in the same region and correlated; the counts are not numbers of independent loci.', '', 'Gene names are nearest annotated gene-body labels, not validated effector genes. Assumed build, multiallelic coding and some original effect-allele conventions remain uncertain. Relative odds ratios apply to the source insomnia phenotype and do not give a person’s absolute risk; the HFRS is a different phenotype from FI and FFS. The [full evidence matrix](shared22_eight_source_evidence_matrix.csv) preserves all eight effects and p-values. See also the [allele crosswalk](shared22_allele_orientation_crosswalk.csv), [regional LD review](shared22_reference_ld_interpretation.md), and [shared-count definition and validation limits](shared22_score_research_guide.md).', '', 'The 22-marker count is an unweighted, unvalidated research prototype. It has not been tested for prediction or calibrated against participant outcomes. Source matrix SHA-256: `'+hashlib.sha256(src.read_bytes()).hexdigest()+'`.']
pathlib.Path('outputs/shared22_mentor_risk_table.md').write_text('\n'.join(parts)+'\n');print('wrote',len(rows),'rows')
